import zipfile, re, xml.etree.ElementTree as ET

NS = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"

z = zipfile.ZipFile("budget.xlsx")
root = ET.fromstring(z.read("xl/worksheets/sheet1.xml"))

# Parse rows into dict of {ref: value}
cells = {}
for row in root.iter(NS + "row"):
    for c in row.iter(NS + "c"):
        ref = c.get("r")
        t = c.get("t", "n")
        v = None
        if t == "inlineStr":
            txts = [t.text or "" for t in c.iter(NS + "t")]
            v = "".join(txts)
        elif t == "n":
            val = c.find(NS + "v")
            if val is not None and val.text:
                v = float(val.text)
        else:
            val = c.find(NS + "v")
            if val is not None and val.text:
                v = val.text
        cells[ref] = v

# Expense rows are rows 11-22 (C column holds amounts, A column the category)
expense_rows = range(11, 23)
total = 0.0
per_cat = {}
for r in expense_rows:
    ref_c = f"C{r}"
    ref_a = f"A{r}"
    amt = cells.get(ref_c)
    cat = cells.get(ref_a)
    if amt is None:
        print(f"Row {r}: no amount at {ref_c}")
        continue
    total += amt
    per_cat[cat] = per_cat.get(cat, 0.0) + amt
    print(f"Row {r}: {cat} | {cells.get('B'+str(r))} | {amt}")

print("\nPer-category totals:")
for k, v in per_cat.items():
    print(f"  {k}: {v}")

print(f"\nTOTAL EXPENSES (rows 11-22): {total}")

# Cross-check with the SUM formula found in the file
for ref, val in cells.items():
    if ref in ("B8", "C23", "B25"):
        print(f"Formula cell {ref}: {val!r}")

